      ('0374c5b6-855d-5b6c-8366-ee1e5f6baca4'::uuid, 'dec25236-b5ef-57ea-8d3f-815041b2fb15'::uuid, 'd'::text, 56::numeric(9,4)),
      ('648f8d24-3c07-5a6d-b9b9-0986861164fd'::uuid, 'dec25236-b5ef-57ea-8d3f-815041b2fb15'::uuid, 'e'::text, 42::numeric(9,4)),
      ('fa7c4cd1-a4a0-505a-b85d-48b58a46e78a'::uuid, '3ad0fd19-990d-54fc-b344-96915203d2d6'::uuid, 'a'::text, 99::numeric(9,4)),
      ('414b728f-462e-5ccf-b77b-4c29c5d4a23a'::uuid, '3ad0fd19-990d-54fc-b344-96915203d2d6'::uuid, 'b'::text, 85::numeric(9,4)),
      ('03a9ac09-9b75-56db-a58b-5b7bec819337'::uuid, '3ad0fd19-990d-54fc-b344-96915203d2d6'::uuid, 'c'::text, 70::numeric(9,4)),
      ('391e51e3-afaf-5b3b-93d6-45757340e5eb'::uuid, '3ad0fd19-990d-54fc-b344-96915203d2d6'::uuid, 'd'::text, 56::numeric(9,4)),
      ('385c1ea0-1fea-57ea-8802-52c04f5c1d91'::uuid, '3ad0fd19-990d-54fc-b344-96915203d2d6'::uuid, 'e'::text, 42::numeric(9,4)),
      ('f988211b-9de1-506d-9a69-2174b4ebdea9'::uuid, '8d269adc-9c49-5c0e-87c6-c0ebc39ce83c'::uuid, 'a'::text, 109::numeric(9,4)),
      ('a5ef6fe6-f880-5027-9165-c44003ecdd0f'::uuid, '8d269adc-9c49-5c0e-87c6-c0ebc39ce83c'::uuid, 'b'::text, 95::numeric(9,4)),
      ('4595297d-00b6-5323-8773-3e7cea6c5776'::uuid, '8d269adc-9c49-5c0e-87c6-c0ebc39ce83c'::uuid, 'c'::text, 81::numeric(9,4)),
      ('70ebfb7f-247b-5cc0-b799-864f32481694'::uuid, '8d269adc-9c49-5c0e-87c6-c0ebc39ce83c'::uuid, 'd'::text, 68::numeric(9,4)),
      ('175f4715-c7fe-5977-b1de-2674d7f4716b'::uuid, '8d269adc-9c49-5c0e-87c6-c0ebc39ce83c'::uuid, 'e'::text, 55::numeric(9,4)),
      ('06c05878-d13c-5e6f-89f7-ae84cbc86831'::uuid, 'a471d38d-5860-58f0-b3c5-b2d1a3d7bb8b'::uuid, 'a'::text, 61::numeric(9,4)),
      ('27777771-4248-59ca-991d-890ae391f129'::uuid, 'a471d38d-5860-58f0-b3c5-b2d1a3d7bb8b'::uuid, 'b'::text, 54::numeric(9,4)),
      ('079ff51d-e3cf-5933-b71e-0ce5e6b8bda5'::uuid, 'a471d38d-5860-58f0-b3c5-b2d1a3d7bb8b'::uuid, 'c'::text, 45::numeric(9,4)),
      ('b1eaab94-abde-56cc-a32b-957c0a82dcda'::uuid, 'a471d38d-5860-58f0-b3c5-b2d1a3d7bb8b'::uuid, 'd'::text, 36::numeric(9,4)),
      ('cdc0edf2-c7d1-594e-827f-d723f083e974'::uuid, 'a471d38d-5860-58f0-b3c5-b2d1a3d7bb8b'::uuid, 'e'::text, 27::numeric(9,4))
    ) AS v(id, combination_id, grade, threshold_mark)
  ),
  actual AS (
    SELECT id, combination_id, grade, threshold_mark
    FROM public.grade_threshold_combination_marks
    WHERE combination_id IN (
      SELECT id FROM public.grade_threshold_combinations
      WHERE publication_id IN (
        SELECT id FROM public.grade_threshold_publications
        WHERE import_run_id = '00000000-0000-4000-8000-000000000010'::uuid
      )
    )
  )
  SELECT
    (SELECT count(*)::int FROM ((SELECT * FROM expected EXCEPT SELECT * FROM actual) UNION ALL (SELECT * FROM actual EXCEPT SELECT * FROM expected)) d),
    (SELECT count(*)::int FROM actual)
  INTO v_d, v_r;
  v_delta := v_delta + v_d + CASE WHEN v_r <> 1059 THEN 1 ELSE 0 END;
  v_rows  := v_rows  + v_r;

  -- ── 12. Per-subject exact count verification (all 5 subjects) ────────────────
  WITH expected_subject_counts AS (
    SELECT * FROM (VALUES
      ('9701'::text, 40, 25, 125, 36, 118, 208),
      ('9702'::text, 40, 25, 125, 36, 118, 208),
      ('9709'::text, 48, 30, 150, 52, 141, 297),
      ('9231'::text, 40, 20, 100, 41, 112, 236),
      ('9618'::text, 22, 14,  70, 19,  53, 110)
    ) AS v(syllabus_code, expected_we, expected_cv, expected_cm, expected_comb, expected_tok, expected_comb_mark)
  ),
  actual_subject_counts AS (
    SELECT
      s.code AS syllabus_code,
      (SELECT count(*)::int FROM public.grade_threshold_weighting_entries e
       JOIN public.grade_threshold_weighting_sources ws ON ws.id = e.weighting_source_id
       WHERE ws.subject_id = s.id AND ws.document_year = 2026 AND ws.exam_series = 'june') AS actual_we,
      (SELECT count(*)::int FROM public.grade_threshold_component_variants cv
       JOIN public.grade_threshold_publications p ON p.id = cv.publication_id
       WHERE p.subject_id = s.id AND p.exam_year = 2026 AND p.exam_series = 'june' AND p.is_active = TRUE) AS actual_cv,
      (SELECT count(*)::int FROM public.grade_threshold_component_marks cm
       JOIN public.grade_threshold_component_variants cv ON cv.id = cm.component_variant_id
       JOIN public.grade_threshold_publications p ON p.id = cv.publication_id
       WHERE p.subject_id = s.id AND p.exam_year = 2026 AND p.exam_series = 'june' AND p.is_active = TRUE) AS actual_cm,
      (SELECT count(*)::int FROM public.grade_threshold_combinations c
       JOIN public.grade_threshold_publications p ON p.id = c.publication_id
       WHERE p.subject_id = s.id AND p.exam_year = 2026 AND p.exam_series = 'june' AND p.is_active = TRUE) AS actual_comb,
      (SELECT count(*)::int FROM public.grade_threshold_combination_tokens ct
       JOIN public.grade_threshold_combinations c ON c.id = ct.combination_id
       JOIN public.grade_threshold_publications p ON p.id = c.publication_id
       WHERE p.subject_id = s.id AND p.exam_year = 2026 AND p.exam_series = 'june' AND p.is_active = TRUE) AS actual_tok,
      (SELECT count(*)::int FROM public.grade_threshold_combination_marks cmark
       JOIN public.grade_threshold_combinations c ON c.id = cmark.combination_id
       JOIN public.grade_threshold_publications p ON p.id = c.publication_id
       WHERE p.subject_id = s.id AND p.exam_year = 2026 AND p.exam_series = 'june' AND p.is_active = TRUE) AS actual_comb_mark
    FROM public.subjects s
    WHERE s.code IN ('9701', '9702', '9709', '9231', '9618')
  )
  SELECT count(*)::int
  INTO v_d
  FROM expected_subject_counts e
  FULL OUTER JOIN actual_subject_counts a USING (syllabus_code)
  WHERE e.expected_we IS DISTINCT FROM a.actual_we
     OR e.expected_cv IS DISTINCT FROM a.actual_cv
     OR e.expected_cm IS DISTINCT FROM a.actual_cm
     OR e.expected_comb IS DISTINCT FROM a.actual_comb
     OR e.expected_tok IS DISTINCT FROM a.actual_tok
     OR e.expected_comb_mark IS DISTINCT FROM a.actual_comb_mark;
  v_delta := v_delta + v_d;

  RETURN QUERY SELECT v_delta, v_rows;
END;
$func$;
